import{_ as e,o as t,c as i,a2 as a}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Codex CLI","description":"通过 CC Switch 或手动配置为 Codex CLI 接入 Tokeness Responses API。","frontmatter":{"title":"Codex CLI","description":"通过 CC Switch 或手动配置为 Codex CLI 接入 Tokeness Responses API。"},"headers":[],"relativePath":"integrations/codex-cli.md","filePath":"integrations/codex-cli.md","lastUpdated":1781532219000}'),d={name:"integrations/codex-cli.md"};function n(o,s,l,p,h,c){return t(),i("div",null,[...s[0]||(s[0]=[a(`<h1 id="codex-cli" tabindex="-1">Codex CLI <a class="header-anchor" href="#codex-cli" aria-label="Permalink to &quot;Codex CLI&quot;">​</a></h1><p>Codex CLI 可以使用自定义模型供应商。Tokeness 按 OpenAI Responses 协议接入，Base URL 统一填写：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.io/v1</span></span></code></pre></div><p>如果你使用 <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a>，它会帮你写入 Codex 的 <code>auth.json</code> 和 <code>config.toml</code>。如果需要手动核对配置，本页也给出文件示例。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model</td><td>从 Tokeness 模型广场复制</td></tr><tr><td>Wire API</td><td><code>responses</code></td></tr></tbody></table><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先准备三项：</p><ol><li>Tokeness API Key。</li><li>Tokeness 模型名。</li><li>可用余额。</li></ol><p>给 Codex 单独建一个 Key：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>codex-cli-local</span></span></code></pre></div><p>后续如果发现 Codex 消耗异常，可以只停用这个 Key，不影响其他工具。</p><h2 id="_2-安装-codex-cli" tabindex="-1">2. 安装 Codex CLI <a class="header-anchor" href="#_2-安装-codex-cli" aria-label="Permalink to &quot;2. 安装 Codex CLI&quot;">​</a></h2><p>确认 Node.js 可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span></span></code></pre></div><p>如果 npm 下载较慢：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry=https://registry.npmmirror.com</span></span></code></pre></div><p>确认命令可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="_3-通过-cc-switch-配置" tabindex="-1">3. 通过 CC Switch 配置 <a class="header-anchor" href="#_3-通过-cc-switch-配置" aria-label="Permalink to &quot;3. 通过 CC Switch 配置&quot;">​</a></h2><ol><li>打开 CC Switch。</li><li>左侧切换到 <code>Codex</code>。</li><li>点击右上角 <code>+</code>。</li><li>如果没有 Tokeness 预设，选择自定义供应商。</li><li>名称填写 <code>Tokeness</code>。</li><li>API Key 填写 Tokeness API Key。</li><li>Base URL 填写 <code>https://n.tokeness.io/v1</code>。</li><li>模型填写 Tokeness 模型广场中的完整模型名。</li><li>API 类型或 Wire API 选择 <code>responses</code>。</li><li>保存并启用。</li></ol><p>切换后关闭当前终端，重新打开一个终端再运行 Codex。Codex CLI 通常在启动时读取配置，旧终端里可能还保留旧环境。</p><h2 id="_4-手动配置参考" tabindex="-1">4. 手动配置参考 <a class="header-anchor" href="#_4-手动配置参考" aria-label="Permalink to &quot;4. 手动配置参考&quot;">​</a></h2><p>如果你想核对 CC Switch 写入的结果，可以查看 Codex 配置目录。</p><p>macOS / Linux：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codex</span></span></code></pre></div><p>Windows PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ChildItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE\\.codex</span></span></code></pre></div><p><code>auth.json</code> 示例：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;OPENAI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的 Tokeness API Key&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>config.toml</code> 示例：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tokeness&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;从 Tokeness 模型广场复制的模型名&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disable_response_storage = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tokeness</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tokeness&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://n.tokeness.io/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wire_api = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;responses&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">requires_openai_auth = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>字段说明：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>model_provider</code></td><td>当前启用的供应商</td></tr><tr><td><code>model</code></td><td>Codex 默认使用的模型</td></tr><tr><td><code>base_url</code></td><td>Tokeness 接口地址</td></tr><tr><td><code>wire_api</code></td><td>Codex 使用 Responses 协议</td></tr><tr><td><code>requires_openai_auth</code></td><td>使用 OpenAI 风格 Bearer Key 鉴权</td></tr></tbody></table><p>如果你用 CC Switch 管理 Codex，不要长期手动改这两个文件。下次在 CC Switch 切换供应商时，手动改动可能会被覆盖。</p><h2 id="_5-验证" tabindex="-1">5. 验证 <a class="header-anchor" href="#_5-验证" aria-label="Permalink to &quot;5. 验证&quot;">​</a></h2><p>重新打开终端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span></code></pre></div><p>输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只回复一句话，说明当前 Codex 已经接入 Tokeness。</span></span></code></pre></div><p>然后到 Tokeness 使用日志确认：</p><ul><li>是否出现一条新请求。</li><li>Key 是否是 Codex 专用 Key。</li><li>模型名是否正确。</li><li>状态码是否成功。</li></ul><h2 id="_6-多模型配置" tabindex="-1">6. 多模型配置 <a class="header-anchor" href="#_6-多模型配置" aria-label="Permalink to &quot;6. 多模型配置&quot;">​</a></h2><p>可以在 CC Switch 中创建多个 Codex 供应商，或在配置中切换 <code>model</code>。</p><table tabindex="0"><thead><tr><th>配置名称</th><th>用途</th></tr></thead><tbody><tr><td><code>Tokeness Codex Coding</code></td><td>日常代码修改</td></tr><tr><td><code>Tokeness Codex Reasoning</code></td><td>复杂分析、方案设计</td></tr><tr><td><code>Tokeness Codex Docs</code></td><td>文档整理、批量改写</td></tr></tbody></table><p>切换后重新打开终端。</p><h2 id="_7-排查" tabindex="-1">7. 排查 <a class="header-anchor" href="#_7-排查" aria-label="Permalink to &quot;7. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td><code>codex</code> 命令不存在</td><td>重新安装，或重启终端</td></tr><tr><td>仍然使用旧模型</td><td>关闭终端重新打开；检查 <code>model_provider</code></td></tr><tr><td>401 Unauthorized</td><td>检查 <code>auth.json</code> 中的 Key</td></tr><tr><td>404 Not Found</td><td>检查 <code>base_url</code> 是否为 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>Responses 相关报错</td><td>检查 <code>wire_api = &quot;responses&quot;</code></td></tr><tr><td>model not found</td><td>从 Tokeness 模型广场重新复制模型名</td></tr><tr><td>Tokeness 无日志</td><td>当前 Codex 没有走 Tokeness 配置，检查供应商是否启用</td></tr></tbody></table>`,50)])])}const g=e(d,[["render",n]]);export{k as __pageData,g as default};
